// resolveShadowRef returns the shadow branch reference, preferring a pre-resolved
// ref when available and falling back to a repo lookup.
func resolveShadowRef(repo *git.Repository, branchName string, preResolved *plumbing.Reference) (ref *plumbing.Reference, exists bool) {
	if preResolved != nil {
		return preResolved, true
	}
	refName := plumbing.NewBranchReferenceName(branchName)
	resolved, err := repo.Reference(refName, true)
	if err != nil {
		return nil, false
	}
	return resolved, true
}

// filterFilesTouched narrows sessionData.FilesTouched to only files present in
// committedFiles. When no prior files were recorded (mid-turn commit), it falls
// back to the committed set minus Entire metadata paths.
func filterFilesTouched(sessionData *ExtractedSessionData, committedFiles map[string]struct{}) {
	if len(committedFiles) == 0 {
		return
	}
	if len(sessionData.FilesTouched) > 0 {
		filtered := make([]string, 0, len(sessionData.FilesTouched))
		for _, f := range sessionData.FilesTouched {
			if _, ok := committedFiles[f]; ok {
				filtered = append(filtered, f)
			}
		}
		sessionData.FilesTouched = filtered
	} else {
		// Mid-turn commits can happen before SaveStep records FilesTouched.
		// In that case, fall back to the actual committed files, excluding
		// Entire's own metadata paths, so the checkpoint still reflects the
		// files captured by this commit.
		sessionData.FilesTouched = committedFilesExcludingMetadata(committedFiles)
	}
}

// extractOrCreateSessionData tries to extract session data from the shadow branch,
// live transcript, or creates empty session data as a fallback. The empty case is
// handled by the skip gate in CondenseSession.
func (s *ManualCommitStrategy) extractOrCreateSessionData(ctx context.Context, repo *git.Repository, ag agent.Agent, shadowHash plumbing.Hash, hasShadowBranch bool, state *SessionState) (*ExtractedSessionData, error) {
	switch {
	case hasShadowBranch:
		// Shadow branch exists (from SaveStep commits) — extract transcript and
		// metadata from the branch tree, preferring the live transcript if fresher.
		data, err := s.extractSessionData(ctx, repo, shadowHash, state.SessionID, state.FilesTouched, state.AgentType, state.TranscriptPath, state.CheckpointTranscriptStart, state.Phase.IsActive())
		if err != nil {
			return nil, fmt.Errorf("failed to extract session data: %w", err)
		}
		return data, nil
	case state.TranscriptPath != "":
		// No shadow branch but a live transcript path is known — read directly
		// from disk. This handles mid-session commits before SaveStep runs.
		if state.Phase.IsActive() {
			prepareTranscriptIfNeeded(ctx, ag, state.TranscriptPath)
		}
		data, err := s.extractSessionDataFromLiveTranscript(ctx, state)
		if err != nil {
			return nil, fmt.Errorf("failed to extract session data from live transcript: %w", err)
		}
		return data, nil
	default:
		// No shadow branch and no transcript path — create empty session data.
		// This happens for sessions where the agent never set TranscriptPath
		// (e.g., Codex hooks may send null transcript_path). The skip gate in
		// CondenseSession will skip condensation if nothing is found.
		logging.Debug(logging.WithComponent(ctx, "checkpoint"),
			"no shadow branch and no transcript path, returning empty session data",
			slog.String("session_id", state.SessionID),
			slog.String("agent_type", string(state.AgentType)),
		)
		return &ExtractedSessionData{
			FilesTouched: state.FilesTouched,
		}, nil
	}
}

// buildCompactTranscript produces compact (v2) transcript forms when v2
// checkpoints are enabled. The transcript must be pre-redacted. Returns
// the compaction duration for timing logs.
func buildCompactTranscript(ctx context.Context, ag agent.Agent, redacted redact.RedactedBytes, state *SessionState, writeOpts *cpkg.WriteCommittedOptions) time.Duration {
	compactStart := time.Now()
	compactCtx, compactSpan := perf.Start(ctx, "compact_transcript_v2")
	if settings.IsCheckpointsV2Enabled(ctx) {
		// Generate scoped compact (only new content) for line counting and offset calculation.
		scopedCompact := compactTranscriptForV2(compactCtx, ag, redacted, state.CheckpointTranscriptStart)
		// Generate full compact (cumulative) for storage — v2 /main replaces
		// the session's transcript.jsonl on each write, so we must include all
		// prior content, not just the new portion.
		writeOpts.CompactTranscript = compactTranscriptForV2(compactCtx, ag, redacted, 0)
		writeOpts.CompactTranscriptStart = computeCompactTranscriptStart(compactCtx, ag, state, redacted.Bytes(), scopedCompact)
	}
	compactSpan.End()
	return time.Since(compactStart)
}

// generateSummary produces an LLM-generated summary of the session transcript.
// The transcript must be pre-redacted to avoid sending secrets to the LLM.
// Returns nil if the scoped transcript is empty or generation fails.
func generateSummary(ctx context.Context, redactedTranscript redact.RedactedBytes, filesTouched []string, state *SessionState) *cpkg.Summary {
	summarizeCtx := logging.WithComponent(ctx, "summarize")
	transcriptBytes := redactedTranscript.Bytes()

	var scopedTranscript []byte
	switch state.AgentType {
	case agent.AgentTypeGemini:
		scoped, sliceErr := geminicli.SliceFromMessage(transcriptBytes, state.CheckpointTranscriptStart)
		if sliceErr != nil {
			logging.Warn(summarizeCtx, "failed to scope Gemini transcript for summary",
				slog.String("session_id", state.SessionID),
				slog.String("error", sliceErr.Error()))
		}
		scopedTranscript = scoped
	case agent.AgentTypeOpenCode:
		scoped, sliceErr := opencode.SliceFromMessage(transcriptBytes, state.CheckpointTranscriptStart)
		if sliceErr != nil {
			logging.Warn(summarizeCtx, "failed to scope OpenCode transcript for summary",
				slog.String("session_id", state.SessionID),
				slog.String("error", sliceErr.Error()))
		}
		scopedTranscript = scoped
	case agent.AgentTypeCodex, agent.AgentTypeClaudeCode, agent.AgentTypeCursor, agent.AgentTypeFactoryAIDroid, agent.AgentTypeUnknown:
		scopedTranscript = transcript.SliceFromLine(transcriptBytes, state.CheckpointTranscriptStart)
	}

	if len(scopedTranscript) == 0 {
		return nil
	}

	generator := buildSummaryGenerator(summarizeCtx)
	// scopedTranscript is sliced from redactedTranscript, which was redacted earlier in CondenseSession.
	summary, err := summarize.GenerateFromTranscript(summarizeCtx, redact.AlreadyRedacted(scopedTranscript), filesTouched, state.AgentType, generator)
	if err != nil {
		logging.Warn(summarizeCtx, "summary generation failed",
			slog.String("session_id", state.SessionID),
			slog.String("error", err.Error()))
		return nil
	}
	logging.Info(summarizeCtx, "summary generated",
		slog.String("session_id", state.SessionID))
	return summary
}

// buildSummaryGenerator returns a Generator based on the configured summary provider.
// Returns nil if no provider is configured (GenerateFromTranscript falls back to ClaudeGenerator).
//
// The return type is the summarize.Generator interface rather than the concrete
// adapter pointer so callers can't accidentally hold a non-nil interface that
// wraps a nil pointer (the classic Go nil-interface footgun).
func buildSummaryGenerator(ctx context.Context) summarize.Generator { //nolint:ireturn // intentional: nil interface avoids nil-pointer-wrapped-in-interface bug
	s, err := settings.Load(ctx)
	if err != nil {
		// Warn (not Debug): this is the auto-summarize hot path on every commit.
		// A settings-load failure silently downgrades the user's configured
		// provider to the default, and Debug would hide that from operators.
		logging.Warn(ctx, "could not load settings for summary provider, using default",
			"error", err.Error())
		return nil
	}
	if s.SummaryGeneration == nil || s.SummaryGeneration.Provider == "" {
		return nil
	}

	providerName := types.AgentName(s.SummaryGeneration.Provider)
	ag, err := agent.Get(providerName)
	if err != nil {
		logging.Warn(ctx, "configured summary provider not available, using default",
			"provider", s.SummaryGeneration.Provider, "error", err.Error())
		return nil
	}

	// Check binary on PATH, not DetectPresence — a repo can use one agent
	// for development while a different agent generates summaries. Fall back
	// silently (Warn log) because this runs in the post-commit hook and a
	// hard error would block the commit.
	if !agent.IsSummaryCLIAvailable(providerName) {
		logging.Warn(ctx, "configured summary provider CLI binary not on PATH, using default",
			"provider", s.SummaryGeneration.Provider)
		return nil
	}

package strategy

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

// resolveTranscriptPath returns the current path to the session's transcript file.
// If the file exists at state.TranscriptPath, that path is returned immediately.
//
// If the file is missing (os.ErrNotExist), the function re-resolves the path
// using the agent's ResolveSessionFile method. This handles agents that relocate
// transcripts mid-session (e.g., Cursor CLI switching from a flat layout
// <dir>/<id>.jsonl to a nested layout <dir>/<id>/<id>.jsonl).
//
// On successful re-resolution, state.TranscriptPath is updated so that
// subsequent reads use the correct path without repeating the resolution.
func resolveTranscriptPath(state *SessionState) (string, error) {
	if state.TranscriptPath == "" {
		return "", errors.New("no transcript path in session state")
	}

	// Fast path: file exists at the stored location.
	if _, err := os.Stat(state.TranscriptPath); err == nil {
		return state.TranscriptPath, nil
	} else if !errors.Is(err, os.ErrNotExist) {
		// Non-ENOENT error (permission denied, etc.) — return as-is.
		return "", fmt.Errorf("failed to access transcript: %w", err)
	}

	// File not found — attempt re-resolution via the agent.
	ag, agErr := agent.GetByAgentType(state.AgentType)
	if agErr != nil {
		return "", fmt.Errorf("transcript not found at %s: %w", state.TranscriptPath, os.ErrNotExist)
	}

	// Extract the session dir and agent session ID from the stored path.
	// Stored path format: <sessionDir>/<agentSessionID>.jsonl
	sessionDir := filepath.Dir(state.TranscriptPath)
	base := filepath.Base(state.TranscriptPath)
	agentSessionID := strings.TrimSuffix(base, filepath.Ext(base))

	resolved := ag.ResolveSessionFile(sessionDir, agentSessionID)
	if resolved == state.TranscriptPath {
		// Agent resolved to the same path — file genuinely doesn't exist.
		return "", fmt.Errorf("transcript not found at %s: %w", state.TranscriptPath, os.ErrNotExist)
	}

	// Check if the re-resolved path exists.
	if _, err := os.Stat(resolved); err != nil {
		return "", fmt.Errorf("transcript not found at %s (also tried %s): %w", state.TranscriptPath, resolved, os.ErrNotExist)
	}

	// Update state so subsequent reads use the correct path.
	state.TranscriptPath = resolved
	return resolved, nil
}

// Package checkpoint provides types and interfaces for checkpoint storage.
//
// A Checkpoint captures a point-in-time within a session, containing either
// full state (Temporary) or metadata with a commit reference (Committed).
//
// See docs/architecture/sessions-and-checkpoints.md for the full domain model.
package checkpoint

import (
	"context"
	"encoding/json"
	"errors"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/redact"

	"github.com/go-git/go-git/v6/plumbing"
)

// Errors returned by checkpoint operations.
var (
	// ErrCheckpointNotFound is returned when a checkpoint ID doesn't exist.
	ErrCheckpointNotFound = errors.New("checkpoint not found")

	// ErrNoTranscript is returned when a checkpoint exists but has no transcript.
	ErrNoTranscript = errors.New("no transcript found for checkpoint")
)

// Checkpoint represents a save point within a session.
type Checkpoint struct {
	// ID is the unique checkpoint identifier
	ID string

	// SessionID is the session this checkpoint belongs to
	SessionID string

	// Timestamp is when this checkpoint was created
	Timestamp time.Time

	// Type indicates temporary (full state) or committed (metadata only)
	Type Type

	// Message is a human-readable description of the checkpoint
	Message string
}

// Type indicates the storage location and lifecycle of a checkpoint.
type Type int

const (
	// Temporary checkpoints contain full state (code + metadata) and are stored
	// on shadow branches (entire/<commit-hash>). Used for intra-session rewind.
	Temporary Type = iota

	// Committed checkpoints contain metadata + commit reference and are stored
	// on the entire/checkpoints/v1 branch. They are the permanent record.
	Committed
)

// Store provides low-level primitives for reading and writing checkpoints.
// This is used by strategies to implement their storage approach.
//
// The interface matches the GitStore implementation signatures directly:
// - WriteTemporary takes WriteTemporaryOptions and returns a result with commit hash and skip status
// - ReadTemporary takes baseCommit (not sessionID) since shadow branches are keyed by commit
// - List methods return implementation-specific info types for richer data
type Store interface {
	// WriteTemporary writes a temporary checkpoint (full state) to a shadow branch.
	// Shadow branches are named entire/<base-commit-short-hash>.
	// Returns a result containing the commit hash and whether the checkpoint was skipped.
	// Checkpoints are skipped (deduplicated) when the tree hash matches the previous checkpoint.
	WriteTemporary(ctx context.Context, opts WriteTemporaryOptions) (WriteTemporaryResult, error)

	// ReadTemporary reads the latest checkpoint from a shadow branch.
	// baseCommit is the commit hash the session is based on.
	// worktreeID is the internal git worktree identifier (empty for main worktree).
	// Returns nil, nil if the shadow branch doesn't exist.
	ReadTemporary(ctx context.Context, baseCommit, worktreeID string) (*ReadTemporaryResult, error)

	// ListTemporary lists all shadow branches with their checkpoint info.
	ListTemporary(ctx context.Context) ([]TemporaryInfo, error)

	// WriteCommitted writes a committed checkpoint to the entire/checkpoints/v1 branch.
	// Checkpoints are stored at sharded paths: <id[:2]>/<id[2:]>/
	WriteCommitted(ctx context.Context, opts WriteCommittedOptions) error

	// ReadCommitted reads a committed checkpoint's summary by ID.
	// Returns only the CheckpointSummary (paths + aggregated stats), not actual content.
	// Use ReadSessionContent to read actual transcript/prompts.
	// Returns nil, nil if the checkpoint does not exist.
	ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error)

	// ReadSessionContent reads the actual content for a specific session within a checkpoint.
	// sessionIndex is 0-based (0 for first session, 1 for second, etc.).
	// Returns the session's metadata, transcript, and prompts.
	ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error)

	// ReadSessionContentByID reads a session's content by its session ID.
	// Useful when you have the session ID but don't know its index within the checkpoint.
	ReadSessionContentByID(ctx context.Context, checkpointID id.CheckpointID, sessionID string) (*SessionContent, error)

	// ListCommitted lists all committed checkpoints.
	ListCommitted(ctx context.Context) ([]CommittedInfo, error)

	// UpdateCommitted replaces the transcript and prompts for an existing
	// committed checkpoint. Used at stop time to finalize checkpoints with the full
	// session transcript (prompt to stop event).
	// Returns ErrCheckpointNotFound if the checkpoint doesn't exist.
	UpdateCommitted(ctx context.Context, opts UpdateCommittedOptions) error
}

// WriteTemporaryResult contains the result of writing a temporary checkpoint.
type WriteTemporaryResult struct {
	// CommitHash is the hash of the created or existing checkpoint commit
	CommitHash plumbing.Hash

	// Skipped is true if the checkpoint was skipped due to no changes
	// (tree hash matched the previous checkpoint)
	Skipped bool
}

// WriteTemporaryOptions contains options for writing a temporary checkpoint.
type WriteTemporaryOptions struct {
	// SessionID is the session identifier
	SessionID string

	// BaseCommit is the commit hash this session is based on
	BaseCommit string

	// WorktreeID is the internal git worktree identifier (empty for main worktree)
	// Used to create worktree-specific shadow branch names
	WorktreeID string

	// ModifiedFiles are files that have been modified (relative paths)
	ModifiedFiles []string

	// NewFiles are files that have been created (relative paths)
	NewFiles []string

	// DeletedFiles are files that have been deleted (relative paths)
	DeletedFiles []string

	// MetadataDir is the relative path to the metadata directory
	MetadataDir string

	// MetadataDirAbs is the absolute path to the metadata directory
	MetadataDirAbs string

	// CommitMessage is the commit subject line
	CommitMessage string

	// AuthorName is the name to use for commits
	AuthorName string

	// AuthorEmail is the email to use for commits
	AuthorEmail string

	// IsFirstCheckpoint indicates if this is the first checkpoint of the session
	// When true, all working directory files are captured (not just modified)
	IsFirstCheckpoint bool
}

// ReadTemporaryResult contains the result of reading a temporary checkpoint.
type ReadTemporaryResult struct {
	// CommitHash is the hash of the checkpoint commit
	CommitHash plumbing.Hash

	// TreeHash is the hash of the tree containing the checkpoint state
	TreeHash plumbing.Hash

	// SessionID is the session identifier from the commit trailer
	SessionID string

	// MetadataDir is the metadata directory path from the commit trailer
	MetadataDir string

	// Timestamp is when the checkpoint was created
	Timestamp time.Time
}

// TemporaryInfo contains summary information about a shadow branch.
type TemporaryInfo struct {
	// BranchName is the full branch name (e.g., "entire/abc1234")
	BranchName string

	// BaseCommit is the short commit hash this branch is based on
	BaseCommit string

	// LatestCommit is the hash of the latest commit on the branch
	LatestCommit plumbing.Hash

	// SessionID is the session identifier from the latest commit
	SessionID string

	// Timestamp is when the latest checkpoint was created
	Timestamp time.Time
}

// WriteCommittedOptions contains options for writing a committed checkpoint.
type WriteCommittedOptions struct {
	// CheckpointID is the stable 12-hex-char identifier
	CheckpointID id.CheckpointID

	// SessionID is the session identifier
	SessionID string

	// Strategy is the name of the strategy that created this checkpoint
	Strategy string

	// Branch is the branch name where the checkpoint was created (empty if detached HEAD)
	Branch string

	// Transcript is the session transcript content (full.jsonl).
	// Must be pre-redacted (via redact.JSONLBytes or redact.AlreadyRedacted for trusted sources).
	Transcript redact.RedactedBytes

	// Prompts contains user prompts from the session
	Prompts []string

	// FilesTouched are files modified during the session
	FilesTouched []string

	// CheckpointsCount is the number of checkpoints in this session
	CheckpointsCount int

	// EphemeralBranch is the shadow branch name (for manual-commit strategy)
	EphemeralBranch string

	// AuthorName is the name to use for commits
	AuthorName string

	// AuthorEmail is the email to use for commits
	AuthorEmail string

	// MetadataDir is a directory containing additional metadata files to copy
	// If set, all files in this directory will be copied to the checkpoint path
	// This is useful for copying task metadata files, subagent transcripts, etc.
	MetadataDir string

	// Task checkpoint fields (for task/subagent checkpoints)
	IsTask    bool   // Whether this is a task checkpoint
	ToolUseID string // Tool use ID for task checkpoints

	// Additional task checkpoint fields for subagent checkpoints
	AgentID                string // Subagent identifier
	CheckpointUUID         string // UUID for transcript truncation when rewinding
	TranscriptPath         string // Path to session transcript file (alternative to in-memory Transcript)
	SubagentTranscriptPath string // Path to subagent's transcript file

	// Incremental checkpoint fields
	IsIncremental       bool   // Whether this is an incremental checkpoint
	IncrementalSequence int    // Checkpoint sequence number
	IncrementalType     string // Tool type that triggered this checkpoint
	IncrementalData     []byte // Tool input payload for this checkpoint

	// Commit message fields (used for task checkpoints)
	CommitSubject string // Subject line for the metadata commit (overrides default)

