package agent_test

import (
	"context"
	"os/exec"
	"slices"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/codex"
	"github.com/entireio/cli/cmd/entire/cli/agent/copilotcli"
	"github.com/entireio/cli/cmd/entire/cli/agent/cursor"
	"github.com/entireio/cli/cmd/entire/cli/agent/geminicli"
)

// catRunner returns a TextCommandRunner that invokes `cat`, which echoes
// stdin to stdout — letting us verify the prompt round-trips through stdin.
// It also captures the args passed to the binary for flag assertions.
func catRunner(capturedArgs *[]string) agent.TextCommandRunner {
	return func(ctx context.Context, _ string, args ...string) *exec.Cmd {
		*capturedArgs = args
		return exec.CommandContext(ctx, "cat")
	}
}

func TestGenerateText_PromptViaStdin(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name          string
		agent         agent.TextGenerator
		requiredFlags []string
		// extraCheck runs agent-specific assertions on the captured args.
		extraCheck func(t *testing.T, args []string)
	}{
		{
			name:          "codex",
			agent:         &codex.CodexAgent{},
			requiredFlags: []string{"exec", "--skip-git-repo-check"},
			extraCheck: func(t *testing.T, args []string) {
				t.Helper()
				if len(args) == 0 || args[len(args)-1] != "-" {
					t.Fatalf("expected trailing %q stdin sentinel, got %v", "-", args)
				}
			},
		},
		{
			name:          "copilot",
			agent:         &copilotcli.CopilotCLIAgent{},
			requiredFlags: []string{"--allow-all-tools", "--disable-builtin-mcps"},
		},
		{
			name:          "cursor",
			agent:         &cursor.CursorAgent{},
			requiredFlags: []string{"--print", "--force", "--trust", "--workspace"},
		},
		{
			name:          "gemini",
			agent:         &geminicli.GeminiCLIAgent{},
			requiredFlags: []string{"-p"},
			extraCheck: func(t *testing.T, args []string) {
				t.Helper()
				pIdx := slices.Index(args, "-p")
				if pIdx < 0 || pIdx+1 >= len(args) || args[pIdx+1] != " " {
					t.Fatalf("expected -p followed by space placeholder, got %v", args)
				}
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()

			var capturedArgs []string
			setRunner(tt.agent, catRunner(&capturedArgs))

			prompt := "this prompt must arrive via stdin, not argv"
			result, err := tt.agent.GenerateText(context.Background(), prompt, "")
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if result != prompt {
				t.Fatalf("stdin round-trip failed: result=%q, want=%q", result, prompt)
			}
			if slices.Contains(capturedArgs, prompt) {
				t.Fatalf("prompt leaked into argv: %v", capturedArgs)
			}
			for _, flag := range tt.requiredFlags {
				if !slices.Contains(capturedArgs, flag) {
					t.Fatalf("expected %q in args, got %v", flag, capturedArgs)
				}
			}
			if tt.extraCheck != nil {
				tt.extraCheck(t, capturedArgs)
			}
		})
	}
}

// setRunner injects a test CommandRunner into any of the 4 supported agent
// types. This is the external-test equivalent of the package-level var
// mutation the old per-package tests used.
func setRunner(tg agent.TextGenerator, runner agent.TextCommandRunner) {
	switch a := tg.(type) {
	case *codex.CodexAgent:
		a.CommandRunner = runner
	case *copilotcli.CopilotCLIAgent:
		a.CommandRunner = runner
	case *cursor.CursorAgent:
		a.CommandRunner = runner
	case *geminicli.GeminiCLIAgent:
		a.CommandRunner = runner
	}
}

	transcriptPath, resolveErr := resolveTranscriptPath(state)
	if resolveErr != nil {
		logging.Warn(logCtx, "finalize: transcript path resolution failed, skipping",
			slog.String("session_id", state.SessionID),
			slog.Any("error", resolveErr),
		)
		state.TurnCheckpointIDs = nil
		return 1 // Count as error - all checkpoints will be skipped
	}

	fullTranscript, err := os.ReadFile(transcriptPath) //nolint:gosec // path validated by resolveTranscriptPath
	if err != nil || len(fullTranscript) == 0 {
		msg := "finalize: empty transcript, skipping"
		if err != nil {
			msg = "finalize: failed to read transcript, skipping"
		}
		logging.Warn(logCtx, msg,
			slog.String("session_id", state.SessionID),
			slog.String("transcript_path", state.TranscriptPath),
			slog.Any("error", err),
		)
		state.TurnCheckpointIDs = nil
		return 1 // Count as error - all checkpoints will be skipped
	}

	// Open repository (needed for shadow branch prompt reading and checkpoint store)
	repo, err := OpenRepository(ctx)
	if err != nil {
		logging.Warn(logCtx, "finalize: failed to open repository",
			slog.String("error", err.Error()),
		)
		state.TurnCheckpointIDs = nil
		return 1 // Count as error - all checkpoints will be skipped
	}

	prompts := readPromptsFromShadowBranch(ctx, repo, state)
	if len(prompts) == 0 {
		prompts = readPromptsFromFilesystem(ctx, state.SessionID)
	}

	// Redact secrets before writing. Checkpoint store methods require
	// pre-redacted in-memory transcript content from callers. The live
	// transcript on disk is still treated as raw/untrusted input, so redact it
	// here before anything is persisted to the metadata branch.
	//
	// On failure: drop the transcript but continue writing checkpoint metadata
	// (attribution, files touched, prompts). Hooks run without user interaction
	// so there is no retry path — preserving partial metadata is better than
	// losing everything. Persisting an unredacted transcript would be worse.
	_, redactSpan := perf.Start(logCtx, "redact_transcript")
	redactedTranscript, redactErr := redact.JSONLBytes(fullTranscript)
	redactSpan.End()
	if redactErr != nil {
		logging.Warn(logCtx, "finalize: transcript redaction failed, dropping transcript",
			slog.String("session_id", state.SessionID),
			slog.String("error", redactErr.Error()),
		)
		redactedTranscript = redact.RedactedBytes{}
	}
	for i, p := range prompts {
		prompts[i] = redact.String(p)
	}

	store := checkpoint.NewGitStore(repo)
	v2Only := settings.IsCheckpointsV2OnlyEnabled(logCtx)

	// Evaluate v2 flag once before the loop to avoid re-reading settings per checkpoint
	var v2Store *checkpoint.V2GitStore
	if settings.IsCheckpointsV2Enabled(logCtx) {
		v2Store = checkpoint.NewV2GitStore(repo, ResolveCheckpointURL(logCtx, "origin"))
	}

	// Update each checkpoint with the full transcript
	for _, cpIDStr := range state.TurnCheckpointIDs {
		cpID, parseErr := id.NewCheckpointID(cpIDStr)
		if parseErr != nil {
			logging.Warn(logCtx, "finalize: invalid checkpoint ID, skipping",
				slog.String("checkpoint_id", cpIDStr),
				slog.String("error", parseErr.Error()),
			)
			errCount++
			continue
		}

		updateOpts := checkpoint.UpdateCommittedOptions{
			CheckpointID: cpID,
			SessionID:    state.SessionID,
			Transcript:   redactedTranscript,
			Prompts:      prompts,
			Agent:        state.AgentType,
		}

		// Generate compact transcript for v2 /main
		if v2Store != nil && redactedTranscript.Len() > 0 {
			finalAg, _ := agent.GetByAgentType(state.AgentType) //nolint:errcheck // ag may be nil for unknown agent types; compactTranscriptForV2 handles nil
			var (
				content *checkpoint.SessionContent
				readErr error
			)
			if v2Only {
				content, readErr = v2Store.ReadSessionContentByID(ctx, cpID, state.SessionID)
			} else {
				content, readErr = store.ReadSessionContentByID(ctx, cpID, state.SessionID)
			}
			startLine := 0
			if readErr == nil && content != nil {
				startLine = content.Metadata.GetTranscriptStart()
			} else {
				errMsg := "unknown"
				if readErr != nil {
					errMsg = readErr.Error()
				}
				logging.Debug(logCtx, "finalize: failed to read checkpoint metadata, using full transcript for compact output",
					slog.String("checkpoint_id", cpIDStr),
					slog.String("session_id", state.SessionID),
					slog.String("error", errMsg),
				)
			}
			updateOpts.CompactTranscript = compactTranscriptForV2(logCtx, finalAg, redactedTranscript, startLine)
		}

		if !v2Only {
			updateErr := store.UpdateCommitted(ctx, updateOpts)
			if updateErr != nil {
				logging.Warn(logCtx, "finalize: failed to update checkpoint",
					slog.String("checkpoint_id", cpIDStr),
					slog.String("error", updateErr.Error()),
				)
				errCount++
				continue
			}
		}

		if v2Store != nil {
			if v2Err := v2Store.UpdateCommitted(logCtx, updateOpts); v2Err != nil {
				attrs := []any{
					slog.String("checkpoint_id", cpIDStr),
					slog.String("error", v2Err.Error()),
				}
				if v2Only {
					logging.Warn(logCtx, "finalize: failed to update checkpoint in v2", attrs...)
					errCount++
					continue
				}
				logging.Warn(logCtx, "v2 dual-write update failed", attrs...)
			}
		}

		logging.Info(logCtx, "finalize: checkpoint updated with full transcript",
			slog.String("checkpoint_id", cpIDStr),
			slog.String("session_id", state.SessionID),
		)
	}

	// Clear turn checkpoint IDs. Do NOT update CheckpointTranscriptStart here — it was
	// already set correctly by PostCommit: condenseAndUpdateState sets it to the total
	// transcript lines when condensing, and carryForwardToNewShadowBranch resets it to 0
	// when carry-forward is active. Overwriting here would break carry-forward by making
	// sessionHasNewContent think the transcript is fully consumed (no growth).
	state.TurnCheckpointIDs = nil

	return errCount
}

